// SigRel-Lazy - relocation demo (GOT/PLT model)
var GOT = {};
function pltCall(name, impl) {
  if (!GOT[name]) { GOT[name] = impl; console.log("  lazy bind: resolved " + name); }
  return GOT[name]();
}
function puts() { return "hello from libc"; }
console.log("Mechanism: SigLazy | Format: SigELF");
console.log("call 1: " + pltCall("puts", puts));
console.log("call 2: " + pltCall("puts", puts) + " (cached, no re-resolve)");
console.log("Lazy binding -> PASS");

